const blobs = [$('Fetch Suggest Teeth').first().json, $('Fetch Suggest Braces').first().json, $('Fetch Suggest Whitening').first().json];
const seen = new Set();
const topics = [];
for (const b of blobs) {
  const raw = b.data !== undefined ? b.data : b;
  const m = String(raw).match(/window\.google\.ac\.h\(([\s\S]*)\)\s*;?\s*$/);
  if (!m) continue;
  try {
    const arr = JSON.parse(m[1]);
    for (const x of (arr[1] || [])) {
      const t = String((x && x[0]) || '').trim();
      if (t.length >= 3 && !seen.has(t)) { seen.add(t); topics.push(t); }
    }
  } catch (e) {}
}
if (!topics.length) throw new Error('YouTube suggest returned zero topics');
return [{ json: { topics: topics.slice(0, 40), total: topics.length } }];

const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';
function extractAngles(text) {
  const starts = [];
  for (let i = 0; i < text.length; i++) { if (text[i] === '{') starts.push(i); }
  const found = [];
  const winners = [];
  for (const s of starts) {
    let depth = 0, inStr = false, esc = false;
    for (let j = s; j < text.length; j++) {
      const c = text[j];
      if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } }
      else if (c === '"') { inStr = true; }
      else if (c === '{') { depth++; }
      else if (c === '}') { depth--; if (depth === 0) { try { const o = JSON.parse(text.slice(s, j + 1)); if (o && Array.isArray(o.angles) && o.angles.length) { found.push(o.angles); winners.push(o); } } catch (e) {} break; } }
    }
  }
  const score = (arr) => arr.reduce((s, a) => s + ((a && (a.topic || a.title || a.name)) ? 1 : 0), 0);
  found.sort((x, y) => score(y) - score(x));
  const best = found.length ? found[0] : [];
  const win = winners.length ? winners[found.indexOf(best)] : null;
  return { list: best.filter((a) => a && (a.topic || a.title || a.name)), post: win && win.linkedin_post ? String(win.linkedin_post) : '' };
}
let got = { list: [], post: '' };
try { got = extractAngles(String(raw)); } catch (e) { got = { list: [], post: '' }; }
let angles = got.list.slice(0, 5);
let post = got.post;
let quick = false;
if (!angles.length) {
  let askRaw = '';
  try { const ch = $('Ask Nemotron For Angles').first().json.choices || []; askRaw = ((ch[0] || {}).message || {}).content || ''; } catch (e) { askRaw = ''; }
  const srcs = [String(raw), String(askRaw)];
  const found = [];
  for (const t of srcs) {
    const re = /angle\s*\d+\s*[:\-\u2013]\s*(.+)/gi;
    let m = null;
    while ((m = re.exec(t)) && found.length < 5) {
      const line = String(m[1]).replace(/[*_`#]/g, '').trim().slice(0, 140);
      if (line && found.indexOf(line) < 0) found.push(line);
    }
    if (found.length) break;
  }
  angles = found.map((f) => ({ topic: f }));
  quick = true;
}
if (!angles.length) throw new Error('Nemotron returned zero usable angles');
const clean = (v) => String(v || '').replace(/[_*\[\]()~`]/g, '');
const pick = (a, keys) => { for (const k of keys) { if (a[k]) return clean(a[k]); } return ''; };
const lines = quick ? angles.map((a, i) => (i + 1) + '. ' + pick(a, ['topic', 'title', 'name'])) : angles.map((a, i) => (i + 1) + '. ' + pick(a, ['topic', 'title', 'name']) + '\nالهوك: ' + pick(a, ['hook', 'hook_line', 'opening']) + '\nالقالب: ' + pick(a, ['replicable_format', 'format', 'template']) + '\nالعمود: ' + pick(a, ['pillar', 'pillar_name', 'category']));
const today = new Date().toISOString().slice(0, 10);
let digest = 'رادار الترند اليومي (' + today + (quick ? ' - مسودة سريعة' : '') + ')\n\n' + lines.join('\n\n');
if (post) { digest += '\n\nلينكدإن (انسخ والصق):\n' + clean(post); }
if (digest.length > 3500) digest = digest.slice(0, 3500);
digest += '\n\nرد بـ (نفذ 1) لتحويل الزاوية لسكريبت';
const src = $('Normalize Suggestion Topics').first().json.topics.join('|');
let h = 0;
for (const ch of src) { h = ((h * 31 + ch.codePointAt(0)) >>> 0); }
const lean = angles.map((a) => ({ topic: clean(String(a.topic || a.title || a.name || '')), hook: clean(String(a.hook || a.hook_line || a.opening || '')) }));
return [{ json: { digest, hash: String(h), angleCount: angles.length, lean: lean } }];

